def migrar_responsables(apps, schema_editor):
    Funcionario = apps.get_model('inventario_tic', 'FuncionarioInventario')
    alias = schema_editor.connection.alias
    personas = {}
    for nombre_modelo in ('Celular', 'HistoricalCelular'):
        Modelo = apps.get_model('inventario_tic', nombre_modelo)
        for registro in Modelo.objects.using(alias).all().iterator():
            nombre = registro.responsable or ''
            if not nombre.strip():
                continue
            clave = (registro.establecimiento_id, nombre)
            if clave not in personas:
                persona = Funcionario.objects.using(alias).create(
                    nombre=nombre, establecimiento_id=registro.establecimiento_id,
                )
                personas[clave] = persona.pk
            Modelo.objects.using(alias).filter(pk=registro.pk).update(responsable_funcionario_id=personas[clave])


def restaurar_responsables(apps, schema_editor):
    alias = schema_editor.connection.alias
    for nombre_modelo in ('Celular', 'HistoricalCelular'):
        Modelo = apps.get_model('inventario_tic', nombre_modelo)
        for registro in Modelo.objects.using(alias).select_related('responsable_funcionario').all().iterator():
            nombre = registro.responsable_funcionario.nombre if registro.responsable_funcionario_id else None
            Modelo.objects.using(alias).filter(pk=registro.pk).update(responsable=nombre)


